"use client";

import { motion } from "motion/react";

export function ShinyBorderButtonTailwind({ label = "Get early access" }) {
  return (
    <button type="button" className="relative inline-flex overflow-hidden rounded-lg bg-zinc-800 p-[1.5px] text-sm font-medium text-zinc-100">
      <motion.span
        aria-hidden
        className="absolute left-1/2 top-1/2 aspect-square w-[300%] -translate-x-1/2 -translate-y-1/2 bg-[conic-gradient(from_0deg,transparent_0_70%,#38bdf8_85%,transparent_100%)]"
        animate={{ rotate: 360 }}
        transition={{ duration: 3, repeat: Infinity, ease: "linear" }}
      />
      <span className="relative rounded-[calc(0.5rem-1.5px)] bg-zinc-900 px-5 py-2.5">{label}</span>
    </button>
  );
}
